  function build(formatId,features){if(!features.length||!features.every(validFeature))throw Error('Nenhuma geometria válida para exportar.');const fmt=formats.find(f=>f.id===formatId);if(!fmt)throw Error('Formato indisponível.');let data;switch(formatId){case 'pdf':data=pdf(features);break;case 'kml':data=kml(features);break;case 'kmz':data=zip([['doc.kml',kml(features)]]);break;case 'shp':data=shapefile(features);break;case 'dxf':data=dxf(features);break;case 'csv':data=csv(features);break;case 'gpx':data=gpx(features);break;default:data=JSON.stringify(fc(features),null,2)}return{bytes:bytes(data),name:slug(features.length===1?features[0].properties.name:'mapeamentos')+'.'+fmt.ext,mime:fmt.mime}}
  window.FieldFormats={formats,stats,parts,validFeature,build,slug,utm};
